INSERT INTO nutrition.recipes (key, dish, name, slot, kcal, protein_g, carbs_g, fat_g, diets, allergens, portion_guide, is_local) VALUES ('jollof-chicken', 'jollof', 'Jollof rice with grilled chicken', 'LUNCH', 620, 38, 78, 16, ARRAY['OMNIVORE','HALAL','OTHER']::text[], ARRAY[]::text[], 'Jollof rice, about 1.5 cups. Grilled chicken thigh, skin off. Side salad.', true) ON CONFLICT (key) DO UPDATE SET dish = EXCLUDED.dish, name = EXCLUDED.name, slot = EXCLUDED.slot, kcal = EXCLUDED.kcal, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, diets = EXCLUDED.diets, allergens = EXCLUDED.allergens, portion_guide = EXCLUDED.portion_guide, is_local = EXCLUDED.is_local;
